import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"Carbonates","description":"","frontmatter":{"title":"Carbonates","mineralGroup":"carbonates"},"headers":[],"relativePath":"classification/mineral-groups/carbonates.md","filePath":"classification/mineral-groups/carbonates.md","lastUpdated":1790876393000}'),s={name:"classification/mineral-groups/carbonates.md"};function o(n,e,l,d,c,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="carbonates" tabindex="-1">Carbonates <a class="header-anchor" href="#carbonates" aria-label="Permalink to &quot;Carbonates&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Carbonates include several distinctive gem families:</p><ul><li><strong>Calcite subgroup</strong>: calcite (incl. Iceland spar), rhodochrosite, magnesite, siderite</li><li><strong>Aragonite subgroup</strong>: aragonite, pearl mother-of-pearl, coral</li><li><strong>Dolomite, malachite, azurite</strong>: complex hydrated or copper-bearing carbonates Most carbonates are soft (Mohs 3–4) and used as carving or ornamental material.</li></ul><h2 id="formula-class" tabindex="-1">Formula Class <a class="header-anchor" href="#formula-class" aria-label="Permalink to &quot;Formula Class&quot;">​</a></h2><p>CO₃²⁻ + divalent metal cations</p><h2 id="crystal-structure" tabindex="-1">Crystal Structure <a class="header-anchor" href="#crystal-structure" aria-label="Permalink to &quot;Crystal Structure&quot;">​</a></h2><p>Planar [CO₃]²⁻ triangular groups coordinate with divalent metal cations (Ca, Mg, Mn, Fe, Cu, Zn, Ba, Sr). Calcite subgroup: trigonal; aragonite subgroup: orthorhombic.</p><h2 id="representative-gem-species" tabindex="-1">Representative Gem Species <a class="header-anchor" href="#representative-gem-species" aria-label="Permalink to &quot;Representative Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Formula</th><th>Subgroup</th></tr></thead><tbody><tr><td>Calcite / 方解石</td><td>CaCO₃</td><td>calcite</td></tr><tr><td>Rhodochrosite / 菱锰矿</td><td>MnCO₃</td><td>calcite</td></tr><tr><td>Magnesite / 菱镁矿</td><td>MgCO₃</td><td>calcite</td></tr><tr><td>Aragonite / 文石</td><td>CaCO₃</td><td>aragonite</td></tr><tr><td>Malachite / 孔雀石</td><td>Cu₂CO₃(OH)₂</td><td>malachite</td></tr><tr><td>Azurite / 蓝铜矿</td><td>Cu₃(CO₃)₂(OH)₂</td><td>azurite</td></tr><tr><td>Smithsonite / 菱锌矿</td><td>ZnCO₃</td><td>calcite</td></tr></tbody></table><p><em>See the <a href="./intro.html">mineral group overview</a>.</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA: Gem Species, Varieties, and Groups</a><span>Relationships among mineral species, gem varieties, and mineral groups</span><small>Open source ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat mineral database</a><span>Mineral names, chemistry, and classification lookup</span><small>Open source ↗</small></li></ul></aside>',12)])])}const h=a(s,[["render",o]]);export{u as __pageData,h as default};
